<script lang="ts">
 import { ArrowRight, Landmark, Wallet, TrendingUp, Layers, ChevronRight, CircleHelp } from 'lucide-svelte';
 import BalanceChart from '$lib/components/ledger/BalanceChart.svelte';
 import { liquidityScenario } from '$lib/ledger-wealth.js';
 import type { WealthOverview } from '$lib/ledger-wealth.js';
 let {data}:{data:{overview:WealthOverview;stale:boolean;error:string|null}}=$props();
 const w=$derived(data.overview);
 const money=(n:string|number,c:string)=>new Intl.NumberFormat('de-CH',{style:'currency',currency:c}).format(Number(n));
 const date=(s:string)=>new Date(s+'T12:00:00').toLocaleDateString('de-CH');
 let selected=$state('');
 const account=$derived(data.overview?.accounts.find(a=>a.id===selected)??data.overview?.accounts[0]);
 const flows=$derived(data.overview?.cashflows.filter(f=>f.account_id===account?.id).slice(-12)??[]);
 const flowMax=$derived(Math.max(1,...flows.flatMap(f=>[Number(f.incoming),Number(f.outgoing)])));
 let scenarioCurrency=$state('CHF');
 let income=$state<number|undefined>();let costs=$state<number|undefined>();let oneOff=$state(0);let reserve=$state(0);
 const initial=$derived(Number(data.overview?.native_cash.find(c=>c.currency===scenarioCurrency)?.amount??0));
 const scenario=$derived(income!==undefined&&costs!==undefined?liquidityScenario(initial,income,costs,oneOff,reserve):null);
 const scenarioPoints=$derived(scenario?.points.map(p=>({date:new Date(Date.UTC(new Date(data.overview!.generated_at).getUTCFullYear(),new Date(data.overview!.generated_at).getUTCMonth()+p.month,new Date(data.overview!.generated_at).getUTCDate())).toISOString().slice(0,10),amount:String(p.amount)}))??[]);
</script>
<div class="wealth">
 <section class="card accounts"><div class="section-head"><div><p class="eyebrow">BELEGTE BESTÄNDE</p><h2>Wo dein Geld liegt</h2></div><small>{w.accounts.length} Konten / Depots</small></div>
  <div class="account-grid">{#each w.accounts as a}<button class:selected={account?.id===a.id} onclick={()=>selected=a.id} aria-pressed={account?.id===a.id}>
   <div class="account-top"><span>{a.label}</span><small>{date(a.as_of)}</small></div><strong>{money(a.total,a.currency)}</strong>
   <div class="allocation" title={`Bargeld ${money(a.cash,a.currency)} · Anlagen / Restwert ${money(a.invested,a.currency)}`}><span style={`width:${Number(a.total)>0?Math.max(0,Math.min(100,Number(a.cash)/Number(a.total)*100)):100}%`}></span></div>
   <div class="account-meta"><span>Bargeld {money(a.cash,a.currency)}</span>{#if Number(a.invested)>0}<span>Anlagen / Restwert {money(a.invested,a.currency)}</span>{/if}</div>
  </button>{/each}</div>
  <p class="caption">Stand {date(w.accounts.map(a=>a.as_of).sort()[0])} bis {date(w.accounts.map(a=>a.as_of).sort().at(-1)!)}. Bargeld ist im Kontowert enthalten; es wird nicht nochmals addiert.</p>
 </section>
 {#if account}
 <section class="history-grid">
  <article class="card history"><div class="section-head"><div><p class="eyebrow">ENTWICKLUNG</p><h2>{account.label}</h2></div><select aria-label="Konto für Verlauf" value={account.id} onchange={(e)=>selected=e.currentTarget.value}>{#each w.accounts as a}<option value={a.id}>{a.label}</option>{/each}</select></div>
   <p class="caption">{account.history_kind} · {account.currency}</p>
   <BalanceChart points={account.history} currency={account.currency} label={`${account.label}: ${account.history_kind}`}/>
   {#if account.history.length===1}<p class="caption">Ein Stichtag ist noch kein Verlauf. Ein längerer Export ergänzt diese Ansicht.</p>{/if}
   <details><summary>Beleg & Prüfungen</summary><p>{account.evidence.filename} · {account.date_basis}</p>{#if account.investment_basis}<p>{account.investment_basis}</p>{/if}<p>Bargeld in Originalwährung: {account.cash_by_currency.map(c=>money(c.amount,c.currency)).join(" · ")}</p><ul>{#each account.checks as c}<li>{c}</li>{/each}{#each account.gaps as g}<li class="gap">{g}</li>{/each}</ul><small class="hash">SHA-256 {account.evidence.sha256}</small></details>
  </article>
  <article class="card flow"><p class="eyebrow">ZU- UND ABGÄNGE</p><h2>Letzte {flows.length||0} Monate</h2>
   {#if flows.length}<div class="legend"><span class="in">Eingang</span><span class="out">Ausgang</span><small>{account.currency}</small></div>
   <div class="bars">{#each flows as f}<div class="bar-row"><time>{f.month.slice(5)}.{f.month.slice(0,4)}</time><div class="bar-track"><div class="bar incoming" style={`width:${Number(f.incoming)/flowMax*100}%`} title={`Eingang ${money(f.incoming,f.currency)}`}></div><div class="bar outgoing" style={`width:${Number(f.outgoing)/flowMax*100}%`} title={`Ausgang ${money(f.outgoing,f.currency)}`}></div></div><span title={`Eingang ${money(f.incoming,f.currency)}, Ausgang ${money(f.outgoing,f.currency)}`}>{money(f.net,f.currency)}</span></div>{/each}</div>
   <p class="caption">Bruttobewegungen dieses Kontos, inklusive Überträge. Das ist noch keine Einnahmen-/Ausgabenrechnung.</p>
   <details><summary>Beträge ansehen</summary><div class="table-wrap"><table><thead><tr><th>Monat</th><th>Eingang</th><th>Ausgang</th></tr></thead><tbody>{#each flows as f}<tr><td>{f.month}</td><td>{money(f.incoming,f.currency)}</td><td>{money(f.outgoing,f.currency)}</td></tr>{/each}</tbody></table></div></details>
   {:else}<div class="empty"><TrendingUp size={26}/><p>Für dieses Depot fehlt eine vollständige Bewegungshistorie.</p><small>Die Bestandswerte oben sind bereits erfasst.</small></div>{/if}
  </article>
 </section>
 {#if account.positions.length}<section class="card"><p class="eyebrow">DEPOTPOSITIONEN · {account.label}</p><div class="table-wrap"><table><thead><tr><th>Wertpapier</th><th>Stück</th><th>Marktwert</th><th>Kostenbasis</th><th>Unrealisiert</th></tr></thead><tbody>{#each account.positions as p}<tr><td><strong>{p.symbol}</strong></td><td>{p.quantity}</td><td>{money(p.value,p.currency)}</td><td>{money(p.cost,p.currency)}</td><td>{money(p.unrealized,p.currency)}</td></tr>{/each}</tbody></table></div><p class="caption">Im Depotwert bereits enthalten · Stand {date(account.as_of)} · keine Kauf-/Verkaufsfunktion</p></section>{/if}
 {/if}
 <section class="card scenario" id="scenario"><div class="section-head"><div><p class="eyebrow">WAS WÄRE, WENN …</p><h2>Deine nächsten zwölf Monate</h2></div><select aria-label="Szenario-Währung" bind:value={scenarioCurrency}>{#each w.native_cash as c}<option value={c.currency}>{c.currency}</option>{/each}</select></div>
 <p class="caption">Rechenbeispiel ab erfasstem Bargeld: <b>{money(initial,scenarioCurrency)}</b>. Originalwährung, ohne Verkauf von Wertpapieren. Fehlende Konten und heutige Salden können das Bild deutlich verändern.</p>
 <div class="scenario-inputs"><label>Monatlicher Eingang<input type="number" min="0" max="100000000" step="0.01" placeholder="Deine Annahme" bind:value={income}/></label><label>Monatlicher Ausgang<input type="number" min="0" max="100000000" step="0.01" placeholder="Deine Annahme" bind:value={costs}/></label><label>Einmalig im 1. Monat (+/−)<input type="number" min="-100000000" max="100000000" step="0.01" bind:value={oneOff}/></label><label>Gewünschte Reserve<input type="number" min="0" max="100000000" step="0.01" bind:value={reserve}/></label></div>
 {#if scenario}<div class="scenario-result"><strong>Nach 12 Monaten: {money(scenario.end,scenarioCurrency)}</strong><span>Monatliche Veränderung {money(scenario.monthlyNet,scenarioCurrency)}</span><span>{scenario.belowReserve!==null?`Reserve unterschritten: ${scenario.belowReserve===0?'bereits zu Beginn':'Monat '+scenario.belowReserve}`:'Reserve bleibt in diesem Szenario erhalten'}</span></div><BalanceChart points={scenarioPoints} currency={scenarioCurrency} label="Liquiditätsszenario für zwölf Monate"/>{:else}<p class="scenario-hint">Trage einen monatlichen Ein- und Ausgang ein, um dein Szenario zu sehen.</p>{/if}
 <p class="caption">Deine Annahmen, keine Prognose. Keine Rendite, Inflation oder Steuerwirkung unterstellt. Eingaben werden nicht gespeichert.</p>
 </section>
 <section class="secondary-grid">
 <article class="card"><p class="eyebrow">WEITERE VERMÖGENSWERTE</p><h2>Bewertungen & Schätzungen</h2>
 {#each w.valuations as v}<div class="value-row"><div><strong>{v.label}</strong><small>{date(v.date)} · externe Bewertung</small></div><b>{money(v.amount,v.currency)}</b></div><p class="caption">{v.condition}</p>{/each}
 {#each w.estimates as e}<div class="value-row"><div><strong>{e.label}</strong><small>Eigene Schätzung</small></div><b>{money(e.low,e.currency)} – {money(e.high,e.currency)}</b></div><details><summary>Grundlage</summary><p>{e.source}</p></details>{/each}
 <p class="caption">Separat von den Finanzwerten oben. Kein verfügbares Bargeld.</p></article>
 <article class="card gaps" id="coverage"><p class="eyebrow"><CircleHelp size={15}/> QUELLENLAGE</p><h2>Was zum Gesamtbild fehlt</h2><ul>{#each w.gaps as g}<li>{g}</li>{/each}</ul>
 <details><summary>Nächster Schritt für die Depots</summary><p>Saxo: Bestandsauszug mit Positionen. IB: Aktivitätsauszug über den vollständigen Zeitraum. Danach werden Einzahlungen, Entnahmen und Wertentwicklung getrennt auswertbar.</p><p>Darauf lässt sich ein beobachtender Trading-Bereich mit Konzentration, Performance, Gebühren und später Paper-Trading aufbauen.</p></details>
 <small>Berechnet {new Date(w.generated_at).toLocaleString('de-CH')} · {w.bank_transaction_count.toLocaleString('de-CH')} Bankbewegungen geprüft</small></article>
 </section>
 <footer>{w.scope}. Lokale Auswertung; keine Buchungen oder Zahlungen ausgelöst. <a href="/ledger/books">Zum Belegabgleich →</a></footer>
</div>
<style>
 .wealth{max-width:1460px;margin:0 auto;padding:28px 36px 70px;color:#1b293d;font:15px/1.5 var(--font-sans,system-ui)}h2{font-size:23px;font-weight:600;letter-spacing:-.025em;margin:6px 0 16px}.eyebrow{display:flex;align-items:center;gap:8px;font:650 11px/1.4 ui-monospace,monospace;letter-spacing:.1em;color:#78869a;margin:0 0 10px}.card{border:1px solid #dce4ee;border-radius:16px;padding:24px;background:#fff;min-width:0;margin-bottom:20px}small,.caption{font-size:12px;color:#7b8799}.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px}.account-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.account-grid button{padding:16px;border:1px solid #e1e7ef;border-radius:12px;background:#fbfcfe;text-align:left;font:inherit;cursor:pointer;color:inherit;min-width:0}.account-grid button:hover,.account-grid button.selected{border-color:#7e9fcc;background:#f5f8fc;box-shadow:0 0 0 1px #aec2df55}.account-top{display:flex;justify-content:space-between;flex-wrap:wrap;gap:5px;font-size:13px}.account-top span{font-weight:600}.account-top small{font-size:10px}.account-grid strong{display:block;font-size:22px;font-weight:500;margin:15px 0 12px;font-variant-numeric:tabular-nums}.allocation{height:5px;background:#8aa0c8;border-radius:4px;overflow:hidden}.allocation span{display:block;height:100%;background:#d8e2ee}.account-meta{display:flex;flex-direction:column;gap:3px;font-size:11px;color:#728197;margin-top:10px}.caption{margin:14px 0 0;line-height:1.6}.history-grid{display:grid;grid-template-columns:1.25fr 1fr;gap:20px}.history :global(svg){margin:22px 0}.history select{max-width:180px}select,input{border:1px solid #d8e1ec;border-radius:8px;background:#fff;padding:9px 10px;font:inherit;color:#32425a}select{font-size:12px}details{margin-top:17px;font-size:12px;color:#738198}summary{cursor:pointer;color:#546b8b}details p{margin:10px 0}details ul{padding-left:18px}.hash{display:block;font:10px/1.5 ui-monospace,monospace;overflow-wrap:anywhere}.gap{color:#a17034}.legend{display:flex;align-items:center;gap:17px;font-size:11px;color:#77869b}.legend span:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:#749bbb;margin-right:6px}.legend .out:before{background:#c59b71}.bars{display:grid;gap:9px;margin:17px 0}.bar-row{display:grid;grid-template-columns:53px 1fr 96px;gap:10px;align-items:center;font-size:10px;color:#7c899b}.bar-row>span{text-align:right;font-variant-numeric:tabular-nums}.bar-track{display:grid;gap:3px}.bar{height:5px;border-radius:2px;min-width:1px}.incoming{background:#749bbb}.outgoing{background:#c59b71}.empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:230px;text-align:center;color:#8995a6}.empty p{max-width:290px;font-size:14px}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{font-weight:500;color:#8894a5;font-size:11px}td,th{padding:12px 10px;border-bottom:1px solid #e7edf3;white-space:nowrap}.scenario-inputs{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:22px 0}.scenario-inputs label{display:grid;gap:8px;font-size:12px;color:#718096}.scenario-inputs input{width:100%;box-sizing:border-box}.scenario-hint{padding:28px 15px;text-align:center;background:#f6f8fb;border-radius:10px;color:#8b97a9;font-size:14px}.scenario-result{display:flex;gap:20px;flex-wrap:wrap;align-items:center;margin:25px 0;color:#677d9c;font-size:13px}.scenario-result strong{font-size:19px;font-weight:550;color:#2c4569}.scenario :global(svg){max-height:270px}.secondary-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.value-row{display:flex;justify-content:space-between;align-items:start;gap:20px;padding:17px 0 5px;border-top:1px solid #e8edf3}.value-row div{display:flex;flex-direction:column;gap:4px}.value-row strong{font-size:13px;font-weight:550}.value-row b{font-weight:500;font-size:13px;white-space:nowrap}.gaps ul{padding-left:19px;color:#697b92;font-size:13px;line-height:1.8}.gaps>small{display:block;margin-top:25px}footer{color:#8a97a7;font-size:11px;line-height:1.7}footer a{color:#567cad;white-space:nowrap;text-decoration:none}
 @media(max-width:1150px){.account-grid{grid-template-columns:1fr 1fr}.history-grid{grid-template-columns:1fr}.scenario-inputs{grid-template-columns:1fr 1fr}}
 @media(max-width:650px){.wealth{padding:20px 15px 60px}.account-grid{grid-template-columns:1fr}.card{padding:19px}.secondary-grid{grid-template-columns:1fr;gap:0}.section-head{align-items:flex-start;flex-direction:column}.scenario-inputs{grid-template-columns:1fr 1fr;gap:10px}.value-row{flex-direction:column;gap:7px}.scenario-inputs input{min-width:0}.scenario-inputs label{font-size:11px}.history select{max-width:100%}}
</style>
